// الفصل الخامس: الضربُ في عددٍ من رقمٍ واحد (الصفّ الرابع)
import { AR, fmt, rnd, pick, shuf, parseNum, parseList } from './mathkit.js';
import { $, $$, num, lst, mcq, ch, open, fld, fnq, star } from './engine.js';
import { chartBox } from './stats.js';
import { T2, KB, LT, FOUR, roundTo, placeQ, roundQ, condQ, condList, tf } from './kit4.js';
import { pieSVG } from './ch3.js';

const T3 = (head, rows) => T2(head, rows.map(r => r.map(x => typeof x === 'number' ? AR(x) : x)));
const MXM = (a, b) => `<span class="mx"><b class="n">${AR(a)}</b><i class="op">×</i><b class="n">${AR(b)}</b></span>`;
/** نواتجُ الضربِ الجزئيّة: k × كلِّ منزلةٍ من a */
const parts = (a, k) => { const S = String(a), P = []; for (let i = S.length - 1; i >= 0; i--) { const d = +S[i] * 10 ** (S.length - 1 - i); if (d) P.push(d); } return P; };
const leadRound = a => roundTo(a, Math.max(0, String(a).length - 1));
/** اضربْ عددًا من عدّةِ أرقامٍ في عددٍ من رقمٍ واحد */
export const mulQ = (tag, a, k, o = {}) => { const r = a * k, P = parts(a, k), e = leadRound(a);
  return num(tag, o.text || `أوجدْ ناتجَ الضرب: ${MXM(a, k)}`, r, { skill: o.skill || 'mul', mul: [a, k], sol: [`قدّرْ: ${AR(e)} × ${AR(k)} = ${AR(e * k)}`, ...(P.length > 1 ? [P.map(d => `${AR(k)} × ${AR(d)} = ${AR(k * d)}`).join(' ، '), `نجمعُ نواتجَ الضربِ الجزئيّة: ${P.map(d => AR(k * d)).join(' + ')} = ${AR(r)}`] : [`${AR(a)} × ${AR(k)} = ${AR(r)}`]), `تحقّقْ: ${AR(r)} قريبٌ من ${AR(e * k)} ✓`], hints: ['اضربْ في الآحادِ أوّلًا، ثم في العشرات، ثم في المئات، وأعدِ التجميعَ عندَ الحاجة.'], ...o }); };
/** الضربُ في مضاعفاتِ ١٠ */
const mul10 = (tag, a, b, o = {}) => num(tag, o.text || `أوجدْ ناتجَ الضربِ ذهنيًّا: ${MXM(a, b)}`, a * b, { skill: 'mul10', sol: (() => { const z = (String(b).match(/0+$/) || [''])[0].length + (String(a).match(/0+$/) || [''])[0].length; const fa = +String(a).replace(/0+$/, ''), fb = +String(b).replace(/0+$/, ''); return [`الحقيقةُ الأساسيّة: ${AR(fa)} × ${AR(fb)} = ${AR(fa * fb)}`, `نضيفُ ${AR(z)} ${z === 1 ? 'صفرًا' : 'أصفار'}: ${AR(a * b)}`]; })(), ...o });
/** التقدير: يقبلُ تقريبَ العددِ الأكبرِ إلى منزلتِه الكبرى */
const estM = (tag, a, k, o = {}) => { const e = leadRound(a) * k, ex = a * k;
  return num(tag, o.text || `قدّرْ ناتجَ ${MXM(a, k)} (قرّبِ العددَ الأكبرَ إلى أكبرِ منزلةٍ فيه)، ثم لاحظْ: هل التقديرُ أكبرُ أم أقلُّ من الإجابةِ الدقيقة؟`, e, { skill: 'est', mistakes: [[ex, 'هذه هي الإجابةُ الدقيقة؛ المطلوبُ التقدير.']], sol: [`${AR(a)} ← ${AR(leadRound(a))} ، ${AR(leadRound(a))} × ${AR(k)} = ${AR(e)}`, `الإجابةُ الدقيقة ${AR(ex)}؛ ${leadRound(a) > a ? 'قرّبْنا إلى قيمةٍ أعلى فالتقديرُ أكبر' : leadRound(a) < a ? 'قرّبْنا إلى قيمةٍ أقلّ فالتقديرُ أقلّ' : 'لم يتغيّرِ العدد'}.`], ...o }); };
const factors = n => { const f = []; for (let i = 1; i <= n; i++) if (n % i === 0) f.push(i); return f; };
const facQ = (tag, n, o = {}) => lst(tag, o.text || `أوجدْ جميعَ قواسمِ العدد ${AR(n)}:`, factors(n), { unordered: true, skill: 'fac', sol: [(() => { const p = []; for (let i = 1; i * i <= n; i++) if (n % i === 0) p.push(`${AR(i)} × ${AR(n / i)}`); return p.join(' ، '); })(), `القواسم: ${factors(n).map(AR).join('، ')}`], hints: ['اكتبْ كلَّ عددينِ حاصلُ ضربِهما يساوي العدد.'], ...o });
const multQ = (tag, n, o = {}) => lst(tag, o.text || `أوجدِ المضاعفاتِ الخمسةَ الأولى للعدد ${AR(n)}:`, [1, 2, 3, 4, 5].map(i => i * n), { skill: 'mult', sol: [[1, 2, 3, 4, 5].map(i => `${AR(n)} × ${AR(i)} = ${AR(n * i)}`).join(' ، ')], ...o });
const reas = (tag, text, yes, why, o = {}) => ch(tag, text + ' (هل الإجابةُ معقولة؟)', ['نعم، معقولة', 'لا، غيرُ معقولة'], yes ? 0 : 1, { skill: 'reason', sol: [why], ...o });
/** نموذجُ الضربِ (مستطيلٌ مجزّأ) */
const areaModel = (a, k) => { const P = parts(a, k).reverse(); return `<div style="display:flex;direction:ltr;justify-content:center;margin:6px 0"><b style="align-self:center;margin-right:6px">${AR(k)}</b>${P.map((d, i) => `<div style="flex:${Math.max(1, Math.log10(d) + 1)};min-width:70px;border:2px solid #555;padding:10px 4px;text-align:center;background:${['#ffd89a', '#a8d0f5', '#c8e8b0'][i % 3]}"><small>${AR(d)}</small><br><b>${AR(k)} × ${AR(d)} = ${AR(k * d)}</b></div>`).join('')}</div>`; };
/** نماذجُ قطعِ دينز: k مجموعات من a (عشرات وآحاد) */
const baseTen = (a, k) => { const t = Math.floor(a / 10), u = a % 10; const g = `<span style="display:inline-flex;gap:2px;align-items:flex-end;margin:0 6px">${'<span style="display:inline-block;width:7px;height:60px;background:#f08a24;border:1px solid #a04a00"></span>'.repeat(t)}<span style="display:inline-grid;grid-template-columns:repeat(2,8px);gap:1px">${'<span style="width:8px;height:8px;background:#f08a24;border:1px solid #a04a00"></span>'.repeat(u)}</span></span>`; return `<div style="text-align:center;direction:ltr">${g.repeat(k)}</div>`; };
function mulTool(el) {
  el.innerHTML = `<div class="row"><input class="ans" data-kp="num" inputmode="none" style="width:110px" value="${AR(132)}"> × <input class="ans" data-kp="num" inputmode="none" style="width:60px" value="${AR(5)}"> <button class="btn sm">اضربْ</button></div><div class="mout"></div>`;
  const go = () => { const [a, k] = $$('input', el).map(i => parseNum(i.value)); if (!(a > 0 && a < 10000 && k > 0 && k < 10 && a % 1 === 0 && k % 1 === 0)) { $('.mout', el).innerHTML = '<div class="meta">اكتبْ عددًا (حتى ٤ أرقام) وعددًا من رقمٍ واحد.</div>'; return; }
    const P = parts(a, k); $('.mout', el).innerHTML = areaModel(a, k) + `<div class="keybox">قدّرْ: ${AR(leadRound(a))} × ${AR(k)} = ${AR(leadRound(a) * k)}<br>${P.map(d => `${AR(k)} × ${AR(d)} = ${AR(k * d)}`).join('<br>')}<br>المجموع: ${P.map(d => AR(k * d)).join(' + ')} = <b>${AR(a * k)}</b></div>`; };
  $('button', el).onclick = go; go();
}
function facTool(el) {
  el.innerHTML = `<div class="row">العدد <input class="ans" data-kp="num" inputmode="none" style="width:80px" value="${AR(24)}"> <button class="btn sm">أظهرِ المستطيلات</button></div><div class="fout"></div>`;
  const go = () => { const n = parseNum($('input', el).value); if (!(n >= 1 && n <= 60 && n % 1 === 0)) { $('.fout', el).innerHTML = '<div class="meta">اكتبْ عددًا من ١ إلى ٦٠.</div>'; return; } const pr = []; for (let i = 1; i * i <= n; i++) if (n % i === 0) pr.push([i, n / i]);
    $('.fout', el).innerHTML = pr.map(([r, c]) => `<div style="margin:6px 0"><b>${AR(r)} × ${AR(c)} = ${AR(n)}</b><div style="display:grid;grid-template-columns:repeat(${c},12px);gap:2px;direction:ltr;justify-content:start">${'<span style="width:12px;height:12px;border-radius:50%;background:#f5c518"></span>'.repeat(n)}</div></div>`).join('') + `<div class="keybox">قواسمُ ${AR(n)}: ${factors(n).map(AR).join('، ')}</div>`; };
  $('button', el).onclick = go; go();
}

/* ═════════ المولّدات ═════════ */
const G = {
  fac: L => facQ('', pick([6, 8, 10, 12, 15, 16, 18, 20, 24, 28, 30, 36].slice(0, 6 + 3 * L))),
  mult: L => multQ('', rnd(2, 6 + 3 * L)),
  mul10: L => { const a = rnd(2, 9), z = rnd(1, 3); return mul10('', a, rnd(2, 9) * 10 ** z); },
  est: L => estM('', rnd(10 ** (1 + L), 10 ** (2 + L) - 1), rnd(2, 9)),
  mul2: L => { const t = rnd(1, 4), u = rnd(0, 2), k = rnd(2, 3); return mulQ('', 10 * t + u, k); },
  mul2r: L => mulQ('', rnd(12, 99), rnd(2, 9)),
  mul3: L => mulQ('', rnd(100, L ? 9999 : 999), rnd(2, 9)),
  reason: L => { const k = rnd(3, 9), a = 10 * rnd(3, 9), need = a * k + pick([-1, 1]) * 10 * rnd(1, 5); return reas('', `تتدرّبُ منى ${AR(a)} دقيقةً يوميًّا. هل من المعقولِ القولُ إنّها تتدرّبُ أكثرَ من ${AR(need)} دقيقةً في ${AR(k)} أيّام؟`, a * k > need, `${AR(a)} × ${AR(k)} = ${AR(a * k)} ${a * k > need ? '&gt;' : '&lt;'} ${AR(need)}`); },
};
const GN = { fac: 'القواسم', mult: 'المضاعفات', mul10: 'الضرب في مضاعفات ١٠', est: 'تقدير نواتج الضرب', mul2: 'الضرب دون إعادة تجميع', mul2r: 'الضرب مع إعادة التجميع', mul3: 'ضرب عدد من ثلاثة أرقام', reason: 'معقولية الإجابة' };
